//! FORM rel reflects exact authored link-relation metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://form-rel.test/submit><input id=area name=q value=Seed><input id=charset type=hidden name=_charset_ value=author></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-rel.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn form_rel_canonical_exact_once_conversion_and_raw_units(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'rel');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get rel'||a.set.name!=='set rel'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'rel')||x.rel!=='')throw 'canonical';var calls=0;x.rel={toString:function(){calls++;return '  UTF-8\ud800  ';},valueOf:function(){throw 'wrong hint';}};if(calls!==1||x.rel!=='  UTF-8\ud800  '||x.getAttributeNS(null,'rel')!==x.rel)throw 'exact raw';x.rel=null;if(x.rel!=='null')throw 'ordinary null';x.rel=undefined;if(x.rel!=='undefined')throw 'ordinary undefined';"#);}
#[test]
fn form_rel_inert_exact_attribute_name_namespace_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','form');x.setAttributeNS('urn:foreign','rel','foreign');x.setAttributeNS(null,'REL','upper');x.setAttributeNS(null,'Rel','other');if(x.rel!=='')throw 'exact key';x.rel='A\ud800Z';var copy=x.cloneNode(false);copy.rel='copy';if(x.rel!=='A\ud800Z'||copy.rel!=='copy'||copy.getAttributeNodeNS(null,'rel')===x.getAttributeNodeNS(null,'rel')||x.getAttributeNS('urn:foreign','rel')!=='foreign'||x.getAttributeNS(null,'Rel')!=='other')throw 'independent copy';"#);}


#[test]
fn form_rel_named_control_precedence_preserves_saved_accessor_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),n=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'rel');n.setAttribute('name','rel');if(x.rel!==n)throw 'named control precedence';var calls=0,watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});a.set.call(x,{toString:function(){calls++;return 'OFF';}});var records=watch.takeRecords();if(calls!==1||records.length!==1||records[0].attributeName!=='rel'||x.rel!==n||a.get.call(x)!=='OFF'||x.getAttributeNS(null,'rel')!=='OFF')throw 'saved authority';a.set.call(x,'off\\ud800');if(a.get.call(x)!=='off\\ud800'||x.getAttributeNS(null,'rel')!=='off\\ud800')throw 'named raw setter';a.set.call(x,'OFF');n.setAttribute('name','q');if(x.rel!=='OFF')throw 'live named removal';");}
#[test]
fn form_rel_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.rel='off';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.form_rel_get(object).map(|_|())}else{bridge.form_rel_set(object,&Value::String("growing-unknown-name-value".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.rel='ON';if(x.rel!=='ON'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn form_rel_attribute_writers_observe_raw_values_and_preserve_dirty_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),editor=document.getElementById('area');editor.value='Edited';x.rel='on';var attribute=x.getAttributeNodeNS(null,'rel'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['rel']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('rel','OFF');","x.setAttributeNS(null,'rel','OFF');","attribute.value='OFF';","attribute.nodeValue='OFF';","attribute.textContent='OFF';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.rel='on';watch.takeRecords();");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.rel!=='OFF'||x.getAttributeNodeNS(null,'rel')!==attribute||records.length!==1||records[0].oldValue!=='on'||records[0].attributeName!=='rel'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('rel');replacement.value='off\ud800';x.setAttributeNodeNS(replacement);if(x.rel!=='off\ud800'||attribute.ownerElement!==null||replacement.ownerElement!==x||replacement.value!=='off\ud800')throw 'raw attribute replacement';"#);}

#[test]
fn form_rel_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'rel'),calls=0;if(a.get.call(x)!=='')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-form-rel.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'on';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://form-rel.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'ON');if(x.rel!=='ON')throw 'fresh recovery';");}

#[test]
fn form_rel_brand_abrupt_conversion_and_prototype_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'rel'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.rel={toString:function(){calls++;x.rel='inner';return ' OUTER ';}};if(calls!==1||x.rel!==' OUTER ')throw 'once';var marker={};try{x.rel={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.rel!==' OUTER '||x.getAttribute('data-side')!=='kept')throw 'abrupt';Object.defineProperty(P,'rel',{get:function(){return 'author';},configurable:true});a.set.call(x,'native');if(x.rel!=='author'||a.get.call(x)!=='native')throw 'saved authority';delete P.rel;if(x.rel!==undefined)throw 'deleted canonical';Object.defineProperty(P,'rel',a);var C=HTMLFormElement;delete window.HTMLFormElement;if(!(x instanceof C)||a.get.call(x)!=='native')throw 'saved constructor';"#);}

#[test]
fn form_rel_keywords_remain_exact_metadata(){let(mut d,mut f,mut p)=fixture();for label in ["noopener","noreferrer","opener","NOOPENER","unknown unknown","  opener  ",""]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('form');x.rel='{label}';if(x.rel!=='{label}'||x.getAttributeNS(null,'rel')!=='{label}')throw 'exact rel';"));}}
